import {taxProfiles} from 'webcommander-sdk';

const response = await taxProfiles.listTaxProfiles(client, {limit: 20});
for (const taxProfile of response.map.tax_profiles) {
    console.log(taxProfile.id, taxProfile.name, taxProfile.default);
}
console.log(response.map.pagination.total);

